#!/usr/bin/env python3
import base64,io,zipfile,argparse,pathlib,subprocess,datetime,tarfile,py_compile
PAYLOAD=''
REPLACEMENT='''def calendar_data():
 status={}
 if TSTATUS.exists():
  try:status=json.loads(TSTATUS.read_text(encoding='utf-8'))
  except Exception:pass
 if not TICS.exists():return {'events':[],'status':status}
 runner=R/'tools/calendar_expand.py';python=R/'.timetree-venv/bin/python'
 result=subprocess.run([str(python),str(runner),str(TICS)],capture_output=True,text=True,timeout=120)
 if result.returncode:
  logging.error('Calendar expansion failed: %s',result.stderr[-1000:])
  return {'events':[],'status':status,'error':'繰り返し予定の展開に失敗しました。サーバーログを確認してください'}
 payload=json.loads(result.stdout);payload['status']=status
 return payload
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--app',default='/home/hems/simplehems-server-v2');a=p.parse_args();root=pathlib.Path(a.app).resolve();server=root/'backend/server.py';text=server.read_text(encoding='utf-8');start=text.find('def calendar_data():');end=text.find('def hotdenki_credentials_public():',start)
 if start<0 or end<0 or 'TICS=' not in text:raise RuntimeError('r50 backend boundaries not found; no changes made')
 python=root/'.timetree-venv/bin/python'
 if not python.exists():raise RuntimeError('TimeTree venv not found')
 stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S');backup=root.parent/('simplehems-before-r52-'+stamp+'.tar.gz')
 with tarfile.open(backup,'w:gz') as tar:
  for name in ('backend','tools','config.json','secrets','data/calendar'):
   if (root/name).exists():tar.add(root/name,arcname=name)
 backup.chmod(0o600)
 print('Backup:',backup,flush=True)
 bundle=zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD)))
 wheels=root/'vendor/timetree-wheels';wheels.mkdir(parents=True,exist_ok=True)
 for name in bundle.namelist():
  if name.startswith('wheels/'):(wheels/pathlib.Path(name).name).write_bytes(bundle.read(name))
 subprocess.run([str(python),'-m','pip','install','--no-index','--find-links',str(wheels),'recurring-ical-events==3.8.2'],check=True)
 helper=root/'tools/calendar_expand.py';helper.write_bytes(bundle.read('calendar_expand.py'))
 py_compile.compile(str(helper),doraise=True)
 # Exercise recurrence parsing before changing the backend.
 subprocess.run([str(python),'-c',"import icalendar,recurring_ical_events; c=icalendar.Calendar.from_ical('BEGIN:VCALENDAR\\nVERSION:2.0\\nBEGIN:VEVENT\\nUID:test\\nDTSTART;VALUE=DATE:20261001\\nDTEND;VALUE=DATE:20261002\\nRRULE:FREQ=DAILY;COUNT=3\\nEXDATE;VALUE=DATE:20261002\\nEND:VEVENT\\nEND:VCALENDAR'); assert len(recurring_ical_events.of(c).between((2026,10,1),(2026,10,5)))==2"],check=True)
 new=text[:start]+REPLACEMENT+'\n'+text[end:];tmp=server.with_suffix('.r52.tmp');tmp.write_text(new,encoding='utf-8');py_compile.compile(str(tmp),doraise=True);tmp.replace(server)
 print('Updated. Restart simplehems and reload the calendar. Credentials and ICS unchanged.')
if __name__=='__main__':main()
